import { expect, test, uniqueName } from "../../fixtures";

test("audit trail of another tenant's vendor is invisible to a Northwind member", { tag: "@AUD-02" }, async ({ apiAs }) => {
  // Arrange: a vendor that exists in the Globex Procurement tenant
  const globex = await apiAs("otherTenant");
  const created = await globex.post("/api/vendors", {
    data: {
      name: uniqueName("Globex Vendor"),
      category: "software",
      contact_email: "ops@globex-procurement.com",
    },
  });
  expect(created.status(), await created.text()).toBe(201);
  const vendor = await created.json();

  // Act: a Northwind member requests that vendor's audit trail
  const member = await apiAs("member");
  const res = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  expect(res.status(), await res.text()).toBe(404);
});
